#!/usr/bin/env bash
# Connection env for the agent user: `psql` just works, S3 vars for scripts, ~/.pgpass.
# Only the agent's own DB role is exposed here — never the owner credentials.

DESCRIPTION="okruženje agenta (PG*, DATABASE_URL, S3_*) u ~/.config/social-agent/agent.env"

agent_env_file() { echo "/home/$AGENT_USER/.config/social-agent/agent.env"; }

agent_env() {
  cat <<EOF
# generated by social-agent modules/65-agent-env.sh — re-run ./setup.sh 65 --force after changing /etc/social-agent/.env
PGHOST=127.0.0.1
PGPORT=5432
PGDATABASE=${POSTGRES_DB}
PGUSER=${PG_AGENT_USER}
DATABASE_URL=postgresql://${PG_AGENT_USER}:${PG_AGENT_PASSWORD}@127.0.0.1:5432/${POSTGRES_DB}
S3_ENDPOINT=${S3_ENDPOINT}
S3_REGION=${S3_REGION}
S3_BUCKET=${S3_BUCKET}
AWS_ACCESS_KEY_ID=${S3_ACCESS_KEY_ID}
AWS_SECRET_ACCESS_KEY=${S3_SECRET_ACCESS_KEY}
AWS_DEFAULT_REGION=${S3_REGION}
AWS_ENDPOINT_URL=${S3_ENDPOINT}
SA_CASES_DIR=${SA_DATA}/cases
SA_SHARED_DIR=${SA_DATA}/shared
EOF
}

check() {
  local f; f="$(agent_env_file)"
  [[ -f "$f" ]] && cmp -s "$f" <(agent_env) || return 1
  [[ -f "/home/$AGENT_USER/.pgpass" ]] || return 1
  as_agent 'psql -tAc "select count(*) from platforms"' &>/dev/null || return 1
}

apply() {
  local f; f="$(agent_env_file)"
  install -d -m 700 -o "$AGENT_USER" -g "$AGENT_USER" "$(dirname "$f")"
  agent_env > "$f"
  chown "$AGENT_USER:$AGENT_USER" "$f"; chmod 600 "$f"

  local pgpass="/home/$AGENT_USER/.pgpass"
  printf '127.0.0.1:5432:%s:%s:%s\nlocalhost:5432:%s:%s:%s\n' \
    "$POSTGRES_DB" "$PG_AGENT_USER" "$PG_AGENT_PASSWORD" \
    "$POSTGRES_DB" "$PG_AGENT_USER" "$PG_AGENT_PASSWORD" > "$pgpass"
  chown "$AGENT_USER:$AGENT_USER" "$pgpass"; chmod 600 "$pgpass"
}
